# Write your MySQL query statement below
SELECT SUB.EMPLOYEE_ID, SUB.NAME, COUNT(SUB.N2) REPORTS_COUNT , ROUND(AVG(SUB.A2), 0) AVERAGE_AGE FROM (SELECT E1.EMPLOYEE_ID, E1.NAME, E1.REPORTS_TO, E1.AGE, E2.NAME N2, E2.AGE A2 FROM EMPLOYEES E1 LEFT JOIN EMPLOYEES E2 ON E1.EMPLOYEE_ID = E2.REPORTS_TO) SUB GROUP BY SUB.EMPLOYEE_ID, SUB.NAME HAVING REPORTS_COUNT > 0 ORDER BY SUB.EMPLOYEE_ID;